<template>
 <view class="home-modules">
  <view v-if="error" class="load-error" @click="load">{{error}} · 点击重试</view>
  <swiper v-if="layout.hero?.enabled&&layout.hero.items.length" class="hero" data-module="hero" :indicator-dots="layout.hero.items.length>1" :autoplay="layout.hero.items.length>1" :interval="5000" circular>
   <swiper-item v-for="(slide,i) in layout.hero.items" :key="i"><view class="slide" :class="{'brand-banner':isBrandBanner(slide.image)}" @click="openSlide(slide)"><view class="hero-photo-frame"><image :src="asset(slide.image,960)" :class="productPhotoClass(slide.image)" :mode="isBrandBanner(slide.image)?'aspectFill':'aspectFit'"/></view><view v-if="slide.title||slide.subtitle" class="hero-copy"><text v-if="isBrandBanner(slide.image)" class="brand-eyebrow">HELUOJIA</text><text class="hero-title">{{slide.title}}</text><text class="subtitle">{{slide.subtitle}}</text><text v-if="isBrandBanner(slide.image)" class="brand-link">探索系列 →</text></view></view></swiper-item>
  </swiper>
  <view v-else-if="layout.hero?.enabled" class="hero hero-empty" data-module="hero"><text>{{layout.hero.title}}</text><text class="subtitle">暂无展示内容</text></view>
  <view v-if="layout.coupons?.enabled" class="module coupon-module" data-module="coupons">
   <view class="section-title"><text>{{layout.coupons.title}}</text><text class="more" @click="go('coupons')">我的券包 ›</text></view>
   <view v-if="moduleErrors.coupons||moduleErrors.owned" class="load-error" @click="load">{{moduleErrors.coupons||moduleErrors.owned}} · 点击重试</view>
   <HorizontalScroll v-if="coupons.length" class="coupon-scroll"><view class="coupon-list"><view v-for="coupon in coupons" :key="coupon.id" class="coupon"><view><text class="coupon-price">¥{{money(coupon.discount_amount)}}</text><text class="subtitle">满{{money(coupon.threshold_amount)}}元可用</text><text class="coupon-name">{{coupon.name}}</text></view><button class="ui-button" :disabled="busy===coupon.id||claimed(coupon)||!!moduleErrors.owned" @click="claim(coupon)">{{claimed(coupon)?'已领取':'立即领取'}}</button></view></view></HorizontalScroll>
   <view v-else-if="!moduleErrors.coupons" class="module-empty coupon-empty"><text>暂无可领取优惠券</text></view>
  </view>
  <view v-if="layout.campaigns?.enabled" class="module" data-module="campaigns">
   <view class="section-title"><text>{{layout.campaigns.title}}</text><text class="more" @click="go('campaigns')">全部活动 ›</text></view>
   <view v-if="moduleErrors.campaigns" class="load-error" @click="load">{{moduleErrors.campaigns}} · 点击重试</view>
   <HorizontalScroll v-else-if="activityProducts.length"><view class="activity-list"><view v-for="entry in activityProducts" :key="entry.key" class="activity-product" @click="go('campaigns',{id:entry.campaign.id})"><image :src="asset(entry.product.image)" mode="aspectFit"/><text class="tag">{{campaignNames[entry.campaign.kind]}}</text><text class="product-name">{{entry.product.name}}</text><text class="subtitle">{{entry.campaign.name}}</text><text class="price">{{entry.priceLabel}}</text><text v-if="soldCountText(entry.product.soldCount)" class="sold-count">{{soldCountText(entry.product.soldCount)}}</text></view></view></HorizontalScroll>
   <view v-else class="module-empty"><text>暂无活动商品</text></view>
  </view>
  <view v-if="layout.products?.enabled" class="module" data-module="products"><view class="section-title"><text>{{layout.products.title}}</text><text class="more" @click="home('category')">更多 ›</text></view><view v-if="featured.length" class="product-grid"><view v-for="p in featured" :key="p.id" class="product" @click="go('product',{id:p.id})"><view class="packshot-frame"><image :src="asset(p.image)" :class="productPhotoClass(p.image)" mode="aspectFit"/></view><text class="product-name">{{p.name}}</text><text class="subtitle">{{p.spec}}</text><text class="price"><text v-if="p.priceLabel" class="subtitle">{{p.priceLabel}}</text>¥{{money(p.price)}}</text><text v-if="soldCountText(p.soldCount)" class="sold-count">{{soldCountText(p.soldCount)}}</text></view></view><view v-else class="module-empty">暂无展示商品</view></view>
  <view v-if="layout.categories?.enabled" class="module" data-module="categories"><view class="section-title"><text>{{layout.categories.title}}</text><text class="more" @click="home('category')">全部 ›</text></view><view v-if="categoryItems.length" class="category-grid"><view v-for="c in categoryItems" :key="c.name" @click="go('search',{category:c.name})"><image v-if="categoryImage(c)" :src="asset(categoryImage(c),320)" mode="aspectFit"/><view v-else class="category-placeholder">{{c.name.slice(0,1)}}</view><text>{{c.name}}</text></view></view><view v-else class="module-empty">暂无商品分类</view></view>
  <view v-if="layout.story?.enabled" class="module" data-module="story"><view v-if="layout.story.title" class="section-title">{{layout.story.title}}</view><swiper v-if="layout.story.items.length" class="story" :class="{'brand-story':layout.story.items.every(s=>isBrandBanner(s.image))}" :indicator-dots="layout.story.items.length>1" :autoplay="layout.story.items.length>1" :interval="5000" circular><swiper-item v-for="(slide,i) in layout.story.items" :key="i"><view class="story-slide" :class="{'brand-banner':isBrandBanner(slide.image)}" @click="openSlide(slide)"><view class="story-photo-frame"><image :src="asset(slide.image,960)" :class="productPhotoClass(slide.image)" :mode="isBrandBanner(slide.image)?'aspectFill':'aspectFit'"/></view><view v-if="slide.title||slide.subtitle" class="story-copy"><text>{{slide.title}}</text><text class="subtitle">{{slide.subtitle}}</text></view></view></swiper-item></swiper><view v-else class="module-empty">暂无展示内容</view></view>
 </view>
</template>
<script>
import {productPhotoClass} from '../services/product-photo.js'
import {soldCountText} from '../services/sold-count.js'
import {request,asset,money,go,home,getToken,notify} from '../services/shop.js'
import HorizontalScroll from './HorizontalScroll.vue'
export default {
 components:{HorizontalScroll},
 props:{categories:{type:Array,default:()=>[]},products:{type:Array,default:()=>[]},refreshTick:{default:0}},
 data(){return{layout:{},campaigns:[],coupons:[],owned:[],error:'',moduleErrors:{coupons:'',campaigns:'',owned:''},loadSequence:0,busy:0,claimKeys:{},campaignNames:{price:'活动价',discount:'满减满折',flash:'限时秒杀',group:'拼团好价',combo:'组合礼遇',gift:'满额赠礼'}}},
 mounted(){this.load()},beforeUnmount(){this.loadSequence++},watch:{refreshTick(){this.load()}},
 computed:{categoryItems(){return this.categories.filter(name=>this.products.some(p=>p.category===name)).map(name=>({name,image:this.layout.categories?.items?.find(c=>c.name===name)?.image||''}))},
  featured(){const ids=this.layout.products?.ids||[];return ids.length?ids.map(id=>this.products.find(p=>Number(p.id)===Number(id))).filter(Boolean):this.products.slice(0,6)},
  activityProducts(){const ids=this.layout.campaigns?.ids||[];const campaigns=ids.length?ids.map(id=>this.campaigns.find(c=>Number(c.id)===Number(id))).filter(Boolean):this.campaigns;return campaigns.flatMap(c=>{let config;try{config=JSON.parse(c.config_json||'{}')}catch{return []}return(config.items||[]).map(i=>{const product=this.products.find(p=>Number(p.id)===Number(i.productId));if(!product)return null;let priceLabel='¥'+money(product.price);if(['price','flash','group'].includes(c.kind))priceLabel='¥'+money(i.price);if(c.kind==='combo')priceLabel='组合价 ¥'+money(config.bundlePrice);if(c.kind==='gift')priceLabel='满'+money(config.threshold)+'元赠';return{key:c.id+'_'+i.productId,campaign:c,product,priceLabel}}).filter(Boolean)}).slice(0,12)}
 },
 methods:{soldCountText,productPhotoClass,asset,money,go,home,isBrandBanner(path){return /heluojia-studio-(hero|cream-banner)-/.test(path||'')},categoryImage(c){return c.image||this.products.find(p=>p.category===c.name)?.image||''},
  async load(){
   const sequence=++this.loadSequence;
   const apply=async(key,pending)=>{try{const value=await pending;if(sequence!==this.loadSequence)return;this[key]=value;if(key==='layout')this.error='';else this.moduleErrors[key]=''}catch(e){if(sequence!==this.loadSequence)return;this[key]=key==='layout'?{}:[];if(key==='layout')this.error=e.message;else this.moduleErrors[key]=e.message}};
   // Each section can render as soon as its own response arrives. A failed coupon request must not hide the storefront.
   await Promise.all([apply('layout',request('/storefront')),apply('campaigns',request('/campaigns?channel=C')),apply('coupons',request('/coupon-campaigns')),apply('owned',getToken()?request('/coupons'):Promise.resolve([]))]);
  },
  claimed(c){return this.owned.filter(x=>Number(x.campaign_id)===Number(c.id)).length>=Number(c.claim_limit)},
  async claim(c){if(!getToken()){uni.setStorageSync('shop-return',{screen:'index',query:{}});return go('login')}if(this.busy||this.claimed(c))return;this.busy=c.id;try{const key=this.claimKeys[c.id]||(this.claimKeys[c.id]='home_claim_'+Date.now()+'_'+Math.random().toString(36).slice(2));await request('/coupon-campaigns/'+c.id+'/claim','POST',{requestKey:key});delete this.claimKeys[c.id];await this.load();uni.showToast({title:'领取成功',icon:'success'})}catch(e){notify(e)}finally{this.busy=0}},
  openSlide(s){if(s.target==='product')return go('product',{id:s.productId});if(s.target==='category')return s.category?go('search',{category:s.category}):home('category');if(['coupons','campaigns','business','distribution','promo-materials'].includes(s.target))go(s.target)}
 }
}
</script>
