ax(0,1fr));gap:20px 12px}.product{min-width:0}.product image{width:100%;height:170px;border-radius:10px}.category-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:18px 10px;text-align:center;font-size:13px}.category-grid image,.category-placeholder{width:52px;height:52px;border-radius:50%;margin:0 auto 8px;display:block}.category-placeholder{background:var(--shop-soft, #eaf5fb);color:var(--shop-ink, #28546c);line-height:52px;font-size:20px}.category-grid text{display:block}.story{height:270px;border-radius:12px;overflow:hidden}.story-slide{height:100%;background:var(--shop-surface, #fdfeff)}.story-slide image{width:100%;height:205px;display:block}.story-copy{padding:10px 14px;font-size:15px}.load-error{padding:14px;color:#9a573a;font-size:13px}
.slide image{width:62%;margin-left:38%}.hero-copy{left:20px;right:61%;bottom:30%}.hero-title{font-size:24px}
image.official-cream-photo{transform:scale(1.25);transform-origin:50% 42%}.detail-gallery{background:var(--shop-surface, #fdfeff)}.catalog-product-image{overflow:hidden;background:var(--shop-surface, #fdfeff)}
.packshot-frame{height:170px;width:100%;overflow:hidden;border-radius:10px;background:var(--shop-surface, #fdfeff)}.product .packshot-frame image{height:100%;width:100%;display:block}.hero-photo-frame{position:absolute;right:0;top:0;width:62%;height:100%;overflow:hidden}.slide .hero-photo-frame image{width:100%;height:100%;margin-left:0}.story-photo-frame{height:205px;overflow:hidden}.story-photo-frame image{width:100%;height:100%;display:block}.product-name{white-space:normal;min-height:42px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}
.brand-banner{position:relative;background:#e4edfa}.brand-banner .hero-photo-frame{width:100%}.brand-banner .hero-copy{left:22px;right:62%;bottom:29%;color:#16305b}.brand-banner .hero-title{font-size:25px;line-height:1.4;letter-spacing:1px}.brand-eyebrow{display:block;font-size:9px;letter-spacing:2.5px;margin-bottom:13px;color:#4e6586}.brand-banner .hero-copy .subtitle{color:#4d6284;line-height:1.7;margin-top:12px;font-size:11px}.brand-link{display:inline-block;margin-top:20px;padding-bottom:5px;font-size:11px;border-bottom:1px solid #788aa8}.brand-story{height:205px}.story-slide.brand-banner .story-photo-frame{height:100%}.story-slide.brand-banner .story-copy{position:absolute;left:16px;top:50%;width:31%;transform:translateY(-50%);padding:0;color:#16305b;font-size:19px;font-weight:600;white-space:pre-line;line-height:1.5}.story-slide.brand-banner .story-copy .subtitle{font-size:10px;font-weight:400;color:#4d6284;margin-top:10px;white-space:normal}.packshot-frame{height:auto;aspect-ratio:1;background:#e5edfa;border-radius:12px}.product .packshot-frame image{width:100%;height:100%}.product-grid{gap:24px 14px}.product-name{font-size:13px;min-height:39px;margin-top:11px}.product>.subtitle{min-height:19px}.category-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.category-grid image{width:64px;height:64px;border:1px solid #e5ebf4}.section-title{color:#243b50}.price{color:#946746}@media(max-width:360px){.brand-banner .hero-title{font-size:22px}.brand-banner .hero-copy{left:18px;right:61%}.story-slide.brand-banner .story-copy{font-size:17px}}
.sold-count{display:block;font-size:11px;line-height:1.6;color:var(--shop-muted, #59727f);margin-top:2px}
